(window.CLAVE_TEST=window.CLAVE_TEST||{})[6]=[{"a":"ART. 53.1 · INFRACCIONES GRAVES","q":[{"i":"6-386","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones graves. Entre las infracciones graves se encuentra la de encontrarse irregularmente en territorio español, por no haber obtenido la prórroga de estancia, carecer de autorización de residencia o tener caducada más de tres meses la mencionada autorización, siempre que:","o":["El interesado no hubiere abandonado el territorio nacional en el plazo de treinta días, salvo que el órgano competente acuerde otra cosa de forma motivada.","El interesado no hubiere solicitado la renovación de la misma en el plazo previsto reglamentariamente.","El interesado hubiere sido sancionado por una infracción leve en el año anterior.","El interesado carezca de medios económicos suficientes para su manutención."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El interesado no hubiere solicitado la renovación de la misma en el plazo previsto reglamentariamente</mark></span>El <span class=\"ref-norma\">art. 53.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"a) Encontrarse irregularmente en territorio español, por no haber obtenido la prórroga de estancia, carecer de autorización de residencia o tener caducada más de tres meses la mencionada autorización, y siempre que el interesado no hubiere solicitado la renovación de la misma en el plazo previsto reglamentariamente.\"</span>"},{"i":"6-387","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones graves. También son infracciones graves contraer matrimonio, simular relación afectiva análoga o constituirse en representante legal de un menor, cuando dichas conductas se realicen:","o":["Con ánimo de lucro o con el propósito de obtener indebidamente un derecho de residencia, siempre que tales hechos no constituyan delito.","Con el propósito de obtener indebidamente la nacionalidad española, aunque tales hechos constituyan delito, conforme al procedimiento que reglamentariamente se establezca.","Con ánimo de lucro, aunque no se pretenda obtener ningún derecho de residencia.","Con el propósito de eludir una orden de expulsión, siempre que tales hechos no constituyan delito."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Con ánimo de lucro o con el propósito de obtener indebidamente un derecho de residencia, siempre que tales hechos no constituyan delito</mark></span>El <span class=\"ref-norma\">art. 53.2.b) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"b) Contraer matrimonio, simular relación afectiva análoga o constituirse en representante legal de un menor, cuando dichas conductas se realicen con ánimo de lucro o con el propósito de obtener indebidamente un derecho de residencia, siempre que tales hechos no constituyan delito.\"</span>"},{"i":"6-388","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones graves. También es infracción grave consentir la inscripción de un extranjero en el Padrón Municipal por parte del titular de una vivienda habilitado para tal fin:","o":["Cuando el extranjero no cuente con autorización de residencia en vigor.","Cuando el titular de la vivienda no resida habitualmente en el municipio.","Cuando el extranjero lleve menos de seis meses residiendo en la vivienda.","Cuando dicha vivienda no constituya el domicilio real del extranjero."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuando dicha vivienda no constituya el domicilio real del extranjero</mark></span>El <span class=\"ref-norma\">art. 53.2.d) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"d) Consentir la inscripción de un extranjero en el Padrón Municipal por parte del titular de una vivienda habilitado para tal fin, cuando dicha vivienda no constituya el domicilio real del extranjero.\"</span>"},{"i":"6-461","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones graves. Son infracciones graves, entre otras:","o":["Encontrarse trabajando en España sin haber solicitado autorización de trabajo por cuenta propia, contando con residencia temporal, en los términos que determine la ley orgánica correspondiente.","El retraso, hasta tres meses, en la solicitud de renovación de las autorizaciones caducadas.","Encontrarse trabajando en España sin haber obtenido autorización de trabajo o autorización administrativa previa para trabajar, cuando no cuente con autorización de residencia válida.","La contratación de un trabajador extranjero cuya autorización no le habilita para trabajar en esa ocupación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Encontrarse trabajando en España sin haber obtenido autorización de trabajo o autorización administrativa previa para trabajar, cuando no cuente con autorización de residencia válida</mark></span>El <span class=\"ref-norma\">art. 53.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"1. Son infracciones graves:\"</span>"}]},{"a":"ART. 53.2 · INFRACCIONES GRAVES","q":[{"i":"6-207","p":"Ley Orgánica 4/2000... El incumplimiento de las medidas impuestas por razón de seguridad pública, de presentación periódica o de alejamiento de fronteras o núcleos de población concretados singularmente, de acuerdo con lo dispuesto en la presente Ley es una infracción:","o":["Muy grave.","Menos grave.","Grave.","Leve."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Grave</mark></span>Es GRAVE, no muy grave. Según el <span class=\"ref-norma\">art. 53.1.d de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Son infracciones graves: [...] d) El incumplimiento de las medidas impuestas por razón de seguridad pública, de presentación periódica o de alejamiento de fronteras o núcleos de población concretados singularmente, de acuerdo con lo dispuesto en la presente Ley.\"</span> (verificado con el texto del temario)."},{"i":"6-211","p":"Ley Orgánica 4/2000... Encontrarse trabajando en España sin haber obtenido autorización de trabajo o autorización administrativa previa para trabajar, cuando no cuente con autorización de residencia válida es una infracción:","o":["Grave.","Muy grave.","Leve.","Menos grave."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Grave</mark></span>Es GRAVE. Lo muy grave es CONTRATAR a trabajadores sin autorización (art. 54.1.d). Según el <span class=\"ref-norma\">art. 53.1.b de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Son infracciones graves: [...] b) Encontrarse trabajando en España sin haber obtenido autorización de trabajo o autorización administrativa previa para trabajar, cuando no cuente con autorización de residencia válida.\"</span> (verificado con el texto del temario)."},{"i":"6-241","p":"Ley Orgánica 4/2000, de 11 de enero, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. Señale la infracción Grave tipificada en el artículo 53:","o":["Encontrarse trabajando en una ocupación, sector de actividad, o ámbito geográfico no contemplado por la autorización de residencia y trabajo de la que es titular.","Encontrarse trabajando en España sin haber obtenido autorización de trabajo o autorización administrativa previa para trabajar, cuando no cuente con autorización de residencia válida.","La omisión o el retraso en la comunicación a las autoridades españolas de los cambios de nacionalidad, de estado civil o de domicilio.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Encontrarse trabajando en España sin haber obtenido autorización de trabajo o autorización administrativa previa para trabajar, cuando no cuente con autorización de residencia válida</mark></span>Según el <span class=\"ref-norma\">art. 53.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"b) Encontrarse trabajando en España sin haber obtenido autorización de trabajo o autorización administrativa previa para trabajar, cuando no cuente con autorización de residencia válida\"</span>. C era también grave (salidas por puestos no habilitados); se sustituye por una leve (Verificado con el texto del temario oficial.)"},{"i":"6-250","p":"(Ley Orgánica 4/2000) Ley Orgánica 4/2000... El incumplimiento de las medidas impuestas por razón de seguridad pública de presentación periódica, es una infracción:","o":["No supone ninguna infracción.","Grave.","Muy grave.","Leve."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Grave</mark></span>Según el <span class=\"ref-norma\">art. 53.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"d) El incumplimiento de las medidas impuestas por razón de seguridad pública, de presentación periódica o de alejamiento de fronteras o núcleos de población concretados singularmente\"</span>. Es infracción grave (Verificado con el texto del temario oficial.)"},{"i":"6-252","p":"(Ley Orgánica 4/2000) Ley Orgánica 4/2000... ¿Por cuál de las siguientes infracciones podrá tramitarse la expulsión de un extranjero por el procedimiento preferente?","o":["Encontrarse trabajando en España sin haber obtenido autorización de trabajo o autorización administrativa previa para trabajar, contando, no obstante, con autorización de residencia válida.","El incumplimiento de las medidas impuestas por razón de seguridad pública, de presentación periódica o de alejamiento de fronteras o núcleos de población concretados singularmente, de acuerdo con lo dispuesto en la presente Ley.","Incidir en reincidencia o falsedad grave en el cumplimiento de la obligación de poner en conocimiento de las autoridades competentes los cambios que afecten a nacionalidad, estado civil o domicilio, siempre que tales hechos no constituyan delito.","La permanencia irregular."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El incumplimiento de las medidas impuestas por razón de seguridad pública, de presentación periódica o de alejamiento de fronteras o núcleos de población concretados singularmente, de acuerdo con lo dispuesto en la presente Ley</mark></span>Según el <span class=\"ref-norma\">art. 53.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"d) El incumplimiento de las medidas impuestas por razón de seguridad pública, de presentación periódica o de alejamiento de fronteras o núcleos de población concretados singularmente, de acuerdo con lo dispuesto en la presente Ley\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-330","p":"Ley Orgánica 4/2000... El incumplimiento de las medidas impuestas por razón de seguridad pública, de presentación periódica o de alejamiento de fronteras o núcleos de población concretados singularmente, de acuerdo con lo dispuesto en la presente Ley es una infracción:","o":["Muy grave.","Menos grave.","Grave.","Leve."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Grave</mark></span>Es GRAVE, no muy grave. Según el <span class=\"ref-norma\">art. 53.1.d de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Son infracciones graves: [...] d) El incumplimiento de las medidas impuestas por razón de seguridad pública, de presentación periódica o de alejamiento de fronteras o núcleos de población concretados singularmente, de acuerdo con lo dispuesto en la presente Ley.\"</span> (verificado con el texto del temario)."},{"i":"6-334","p":"Ley Orgánica 4/2000... Encontrarse trabajando en España sin haber obtenido autorización de trabajo o autorización administrativa previa para trabajar, cuando no cuente con autorización de residencia válida es una infracción:","o":["Grave.","Muy grave.","Leve.","Menos grave."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Grave</mark></span>Es GRAVE. Lo muy grave es CONTRATAR a trabajadores sin autorización (art. 54.1.d). Según el <span class=\"ref-norma\">art. 53.1.b de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Son infracciones graves: [...] b) Encontrarse trabajando en España sin haber obtenido autorización de trabajo o autorización administrativa previa para trabajar, cuando no cuente con autorización de residencia válida.\"</span> (verificado con el texto del temario)."},{"i":"6-ia-1234","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones graves. Es infracción grave incurrir en ocultación dolosa o falsedad grave en el cumplimiento de la obligación de poner en conocimiento de las autoridades competentes los cambios que afecten a nacionalidad, estado civil o domicilio, así como incurrir en falsedad en la declaración de los datos obligatorios para cumplimentar el alta en el padrón municipal:","o":["aunque tales hechos constituyan delito o falta.","cuando exista reincidencia en un año.","siempre que medie ánimo de lucro.","siempre que tales hechos no constituyan delito."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">siempre que tales hechos no constituyan delito</mark></span>El <span class=\"ref-norma\">art. 53.1.c) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"así como incurrir en falsedad en la declaración de los datos obligatorios para cumplimentar el alta en el padrón municipal a los efectos previstos en esta Ley, siempre que tales hechos no constituyan delito\"</span>. Coletilla de subsidiariedad: siempre que no constituyan delito. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1235","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones graves. Es infracción grave la comisión de una tercera infracción leve, siempre que en un plazo de __________ anterior hubiera sido sancionado por dos faltas leves de la misma naturaleza.","o":["seis meses","dos años","un año","tres meses"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">un año</mark></span>El <span class=\"ref-norma\">art. 53.1.e) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"e) La comisión de una tercera infracción leve, siempre que en un plazo de un año anterior hubiera sido sancionado por dos faltas leves de la misma naturaleza\"</span>. La reiteración se mide en el plazo de un año anterior. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1237","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones graves. Es infracción grave no dar de alta en la Seguridad Social al trabajador extranjero cuya autorización de residencia y trabajo por cuenta ajena hubiera solicitado el empresario. No obstante, estará exento de esta responsabilidad el empresario que comunique a las autoridades competentes:","o":["la concurrencia de razones sobrevenidas que puedan poner en riesgo objetivo la viabilidad de la empresa o que, conforme a la legislación, impidan el inicio de dicha relación.","la renuncia del trabajador extranjero al puesto de trabajo antes de su entrada en España, siempre que lo acredite documentalmente ante la autoridad consular.","la modificación de la situación nacional de empleo en esa ocupación desde la presentación de la solicitud de autorización.","la imposibilidad de registrar el contrato en los Servicios Públicos de Empleo por causas ajenas a su voluntad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la concurrencia de razones sobrevenidas que puedan poner en riesgo objetivo la viabilidad de la empresa o que, conforme a la legislación, impidan el inicio de dicha relación</mark></span>El <span class=\"ref-norma\">art. 53.2.a) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"No obstante, estará exento de esta responsabilidad el empresario que comunique a las autoridades competentes la concurrencia de razones sobrevenidas que puedan poner en riesgo objetivo la viabilidad de la empresa o que, conforme a la legislación, impidan el inicio de dicha relación\"</span>. La exención exige comunicar razones sobrevenidas que pongan en riesgo la viabilidad de la empresa o impidan el inicio de la relación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1238","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones graves. En la infracción grave de consentir la inscripción de un extranjero en el Padrón Municipal por parte del titular de una vivienda habilitado para tal fin, cuando dicha vivienda no constituya el domicilio real del extranjero:","o":["se incurrirá en una única infracción con independencia del número de inscritos.","se incurrirá en infracción muy grave si los inscritos son más de tres.","solo habrá infracción si el titular de la vivienda obtiene un beneficio.","se incurrirá en una infracción por cada persona indebidamente inscrita."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">se incurrirá en una infracción por cada persona indebidamente inscrita</mark></span>El <span class=\"ref-norma\">art. 53.2.d) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Se incurrirá en una infracción por cada persona indebidamente inscrita\"</span>. Hay una infracción por cada persona indebidamente inscrita; si media ánimo de lucro, es muy grave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"ART. 54.1 · INFRACCIONES MUY GRAVES","q":[{"i":"6-389","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones muy graves. Es infracción muy grave simular la relación laboral con un extranjero, cuando dicha conducta se realice con ánimo de lucro o con el propósito de obtener indebidamente derechos reconocidos en esta Ley:","o":["Aunque tales hechos constituyan delito.","Siempre que medie reincidencia en el plazo de un año.","Siempre que tales hechos no constituyan delito.","Siempre que se perjudique a más de un trabajador extranjero."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Siempre que tales hechos no constituyan delito</mark></span>El <span class=\"ref-norma\">art. 54.1.f) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"f) Simular la relación laboral con un extranjero, cuando dicha conducta se realice con ánimo de lucro o con el propósito de obtener indebidamente derechos reconocidos en esta Ley, siempre que tales hechos no constituyan delito.\"</span>"},{"i":"6-390","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones muy graves. Es infracción muy grave el transporte de extranjeros hasta el territorio español por los sujetos responsables del transporte, sin que hubieran comprobado:","o":["La residencia legal de los extranjeros transportados en el Estado de embarque.","La validez y vigencia de los pasaportes, títulos de viaje o documentos de identidad pertinentes, como, en su caso, del correspondiente visado.","La existencia de medios económicos suficientes para su manutención durante la estancia, sin perjuicio de lo que establezcan los tratados internacionales.","La validez y vigencia del pasaporte, con exclusión del visado correspondiente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La validez y vigencia de los pasaportes, títulos de viaje o documentos de identidad pertinentes, como, en su caso, del correspondiente visado</mark></span>El <span class=\"ref-norma\">art. 54.2.b) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"b) El transporte de extranjeros por vía aérea, marítima o terrestre, hasta el territorio español, por los sujetos responsables del transporte, sin que hubieran comprobado la validez y vigencia, tanto de los pasaportes, títulos de viaje o documentos de identidad pertinentes, como, en su caso, del correspondiente visado\"</span>"},{"i":"6-462","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones muy graves. Es infracción muy grave realizar, con ánimo de lucro, la infracción prevista en la letra d) del apartado 2 del artículo anterior, que consiste en:","o":["Simular la relación laboral con un extranjero con el propósito de obtener indebidamente derechos reconocidos en la Ley, salvo que el órgano competente acuerde otra cosa de forma motivada, conforme al procedimiento que reglamentariamente se establezca.","Consentir la inscripción de un extranjero en el Padrón Municipal por parte del titular de una vivienda habilitado para tal fin, cuando dicha vivienda no constituya el domicilio real del extranjero.","Contraer matrimonio con un extranjero para obtener indebidamente un derecho de residencia.","Inducir, promover, favorecer o facilitar la inmigración clandestina de personas en tránsito."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Consentir la inscripción de un extranjero en el Padrón Municipal por parte del titular de una vivienda habilitado para tal fin, cuando dicha vivienda no constituya el domicilio real del extranjero</mark></span>El <span class=\"ref-norma\">art. 54.1.e) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"e) Realizar, con ánimo de lucro, la infracción prevista en la letra d) del apartado 2 del artículo anterior.\"</span>"}]},{"a":"ART. 54.2 · INFRACCIONES MUY GRAVES (transportistas)","q":[{"i":"6-17","p":"Ley Orgánica 4/2000. Infracciones Graves. ¿Cuál de los siguientes NO es una infracción grave?","o":["Contraer matrimonio, simular relación afectiva o constituirse en representante legal de un menor, cuando dichas conductas se realicen con ánimo de lucro o con el propósito de obtener indebidamente un derecho de residencia siempre que tales hechos no constituyan delito.","Promover la permanencia irregular en España de un extranjero, cuando su entrada legal haya contado con una invitación expresa del infractor y continúe a su cargo una vez transcurrido el período de tiempo permitido por su visado o autorización.","Consentir la inscripción de un extranjero en el Padrón Municipal por parte del titular de una vivienda habilitado para tal fin, cuando dicha vivienda no constituya el domicilio real del extranjero.","Inducir, promover, favorecer o facilitar con ánimo de lucro, individualmente o formando parte de una organización, la inmigración clandestina de personas en tránsito o con destino al territorio español o su permanencia en el mismo, siempre que el hecho no constituya delito."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Inducir, promover, favorecer o facilitar con ánimo de lucro, individualmente o formando parte de una organización, la inmigración clandestina de personas en tránsito o con destino al territorio español o su permanencia en el mismo, siempre que el hecho no constituya delito</mark></span>Según el <span class=\"ref-norma\">art. 54.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"b) Inducir, promover, favorecer o facilitar con ánimo de lucro, individualmente o formando parte de una organización, la inmigración clandestina de personas en tránsito o con destino al territorio español o su permanencia en el mismo, siempre que el hecho no constituya delito\"</span>. Es infracción MUY GRAVE; A, B y C son graves (se corrige B, que venía alterada) (Verificado con el texto del temario oficial.)"},{"i":"6-46","p":"Ley Orgánica 4/2000. Infracciones Graves. ¿Cuál de los siguientes NO es una infracción grave?","o":["Contraer matrimonio, simular relación afectiva o constituirse en representante legal de un menor, cuando dichas conductas se realicen con ánimo de lucro o con el propósito de obtener indebidamente un derecho de residencia siempre que tales hechos no constituyan delito.","Promover la permanencia irregular en España de un extranjero, cuando se haya denegado su entrada legal, o haya expirado la autorización de residencia, o se haya incumplido la obligación de salir en plazo.","Consentir la inscripción de un extranjero en el Padrón Municipal por parte del titular de una vivienda habilitado para tal fin, cuando dicha vivienda no constituya el domicilio real del extranjero.","Inducir, promover, favorecer o facilitar con ánimo de lucro, individualmente o formando parte de una organización, la inmigración clandestina de personas en tránsito o con destino al territorio español o su permanencia en el mismo, siempre que el hecho no constituya delito."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Inducir, promover, favorecer o facilitar con ánimo de lucro, individualmente o formando parte de una organización, la inmigración clandestina de personas en tránsito o con destino al territorio español o su permanencia en el mismo, siempre que el hecho no constituya delito</mark></span>La C (consentir la inscripción en el Padrón de quien no reside en la vivienda) SÍ es grave (art. 53.2.d); solo es muy grave si hay ánimo de lucro (art. 54.1.e). La D es MUY GRAVE. Según el <span class=\"ref-norma\">art. 54.1.b de la LO 4/2000</span>: <span class=\"ref-concepto\">\"Son infracciones muy graves: [...] b) Inducir, promover, favorecer o facilitar con ánimo de lucro, individualmente o formando parte de una organización, la inmigración clandestina de personas en tránsito o con destino al territorio español o su permanencia en el mismo, siempre que el hecho no constituya delito.\"</span> (verificado con el texto del temario)."},{"i":"6-ia-1239","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones muy graves. Realizar, con ánimo de lucro, la conducta de consentir la inscripción de un extranjero en el Padrón Municipal en una vivienda que no constituya su domicilio real es una infracción:","o":["grave.","leve.","muy grave.","grave, con multa agravada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">muy grave</mark></span>El <span class=\"ref-norma\">art. 54.1.e) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"e) Realizar, con ánimo de lucro, la infracción prevista en la letra d) del apartado 2 del artículo anterior\"</span>. Sin ánimo de lucro es grave; con ánimo de lucro, muy grave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1240","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones muy graves. Es infracción muy grave la comisión de una tercera infracción grave siempre que en un plazo de un año anterior hubiera sido sancionado por:","o":["dos faltas graves de cualquier naturaleza.","dos faltas graves de la misma naturaleza.","una falta grave y dos leves de la misma naturaleza.","dos faltas graves con resolución judicial firme."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">dos faltas graves de la misma naturaleza</mark></span>El <span class=\"ref-norma\">art. 54.1.g) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"g) La comisión de una tercera infracción grave siempre que en un plazo de un año anterior hubiera sido sancionado por dos faltas graves de la misma naturaleza\"</span>. Exige dos faltas graves de la misma naturaleza en el año anterior. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1241","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones muy graves. Es infracción muy grave el incumplimiento de la obligación que tienen los transportistas de hacerse cargo sin pérdida de tiempo del extranjero transportado que, por deficiencias en la documentación, no haya sido autorizado a entrar en España. Esta obligación incluirá:","o":["los gastos de mantenimiento del citado extranjero y, si así lo solicitan las autoridades encargadas del control de entrada, los derivados de su transporte.","los gastos de mantenimiento del citado extranjero durante un máximo de setenta y dos horas y los de su internamiento, si fuera acordado por el Juez de Instrucción.","únicamente los gastos derivados del transporte del extranjero hasta el Estado que haya expedido el documento de viaje.","los gastos de mantenimiento y de asistencia letrada del extranjero, así como los de su transporte al país de origen."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los gastos de mantenimiento del citado extranjero y, si así lo solicitan las autoridades encargadas del control de entrada, los derivados de su transporte</mark></span>El <span class=\"ref-norma\">art. 54.2.c) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"Esta obligación incluirá los gastos de mantenimiento del citado extranjero y, si así lo solicitan las autoridades encargadas del control de entrada, los derivados del transporte de dicho extranjero\"</span>. Incluye el mantenimiento y, si lo solicitan las autoridades de control, el transporte. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1242","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones muy graves. No se considerará infracción el hecho de transportar hasta la frontera española a un extranjero que, habiendo presentado sin demora su solicitud de protección internacional:","o":["ésta le sea concedida.","carezca de visado de tránsito.","proceda de un país seguro.","ésta le sea admitida a trámite."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">ésta le sea admitida a trámite</mark></span>El <span class=\"ref-norma\">art. 54.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"no se considerará infracción a la presente Ley el hecho de transportar hasta la frontera española a un extranjero que, habiendo presentado sin demora su solicitud de protección internacional, ésta le sea admitida a trámite\"</span>. Basta con que la solicitud sea admitida a trámite; no hace falta que se conceda. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"6-ia-1243","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Infracciones muy graves. Es infracción muy grave la realización de conductas de discriminación por motivos raciales, étnicos, nacionales o religiosos:","o":["aunque el hecho constituya delito.","cuando sean cometidas por funcionarios públicos.","siempre que el hecho no constituya delito.","siempre que medie reincidencia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">siempre que el hecho no constituya delito</mark></span>El <span class=\"ref-norma\">art. 54.1.c) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"c) La realización de conductas de discriminación por motivos raciales, étnicos, nacionales o religiosos, en los términos previstos en el artículo 23 de la presente Ley, siempre que el hecho no constituya delito\"</span>. Infracción muy grave, subsidiaria del delito. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"ART. 55.2 · QUIÉN INSTRUYE Y QUIÉN SANCIONA","q":[{"i":"6-391","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Sanciones. Para la graduación de las sanciones, el órgano competente en imponerlas se ajustará a:","o":["Criterios de proporcionalidad, valorando el grado de culpabilidad y, en su caso, el daño producido o el riesgo derivado de la infracción y su trascendencia.","Criterios de legalidad, valorando la reincidencia y la capacidad económica del infractor.","Criterios de proporcionalidad, valorando únicamente el grado de culpabilidad del infractor, en los términos que determine la ley orgánica correspondiente, salvo que el órgano competente acuerde otra cosa de forma motivada.","Criterios de oportunidad, atendiendo a las instrucciones del Ministerio del Interior."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Criterios de proporcionalidad, valorando el grado de culpabilidad y, en su caso, el daño producido o el riesgo derivado de la infracción y su trascendencia</mark></span>El <span class=\"ref-norma\">art. 55.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"3. Para la graduación de las sanciones, el órgano competente en imponerlas se ajustará a criterios de proporcionalidad, valorando el grado de culpabilidad y, en su caso, el daño producido o el riesgo derivado de la infracción y su trascendencia.\"</span>"},{"i":"6-392","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Sanciones. Para la determinación de la cuantía de la sanción se tendrá especialmente en cuenta:","o":["El grado de culpabilidad del infractor.","La existencia de reincidencia en el plazo de un año.","El daño producido por la infracción y su trascendencia.","La capacidad económica del infractor."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La capacidad económica del infractor</mark></span>El <span class=\"ref-norma\">art. 55.4 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"4. Para la determinación de la cuantía de la sanción se tendrá especialmente en cuenta la capacidad económica del infractor.\"</span>"}]},{"a":"ART. 56 · PRESCRIPCIÓN DE LAS INFRACCIONES Y DE LAS SANCIONES","q":[{"i":"6-393","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Prescripción. Si la sanción impuesta fuera la de expulsión del territorio nacional, la prescripción no empezará a contar hasta que haya transcurrido el período de prohibición de entrada fijado en la resolución con un máximo de:","o":["Cinco años.","Tres años.","Diez años.","Quince años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Diez años</mark></span>El <span class=\"ref-norma\">art. 56.3 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"3. Si la sanción impuesta fuera la de expulsión del territorio nacional la prescripción no empezará a contar hasta que haya transcurrido el período de prohibición de entrada fijado en la resolución con un máximo de diez años.\"</span>"}]},{"a":"ART. 57.5 · LA SANCIÓN DE EXPULSIÓN NO PODRÁ SER IMPUESTA","q":[{"i":"6-394","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Expulsión del territorio. Antes de adoptar la decisión de la expulsión de un residente de larga duración, deberá tomarse en consideración:","o":["La existencia de antecedentes penales en España y en su país de origen, así como su situación laboral, conforme al procedimiento que reglamentariamente se establezca, sin perjuicio de lo que establezcan los tratados internacionales.","El tiempo de su residencia en España y los vínculos creados, su edad, las consecuencias para el interesado y para los miembros de su familia, y los vínculos con el país al que va a ser expulsado.","El tiempo de su residencia en España y la capacidad económica del extranjero y de su familia.","Su edad, su estado de salud y el parecer de la Comunidad Autónoma de residencia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El tiempo de su residencia en España y los vínculos creados, su edad, las consecuencias para el interesado y para los miembros de su familia, y los vínculos con el país al que va a ser expulsado</mark></span>El <span class=\"ref-norma\">art. 57.5.b) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"b) Los residentes de larga duración. Antes de adoptar la decisión de la expulsión de un residente de larga duración, deberá tomarse en consideración el tiempo de su residencia en España y los vínculos creados, su edad, las consecuencias para el interesado y para los miembros de su familia, y los vínculos con el país al que va a ser expulsado.\"</span>"},{"i":"6-395","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Expulsión del territorio. La expulsión no podrá ser ejecutada cuando ésta conculcase el principio de:","o":["No devolución, o afecte a las mujeres embarazadas, cuando la medida pueda suponer un riesgo para la gestación o la salud de la madre.","Proporcionalidad, o afecte a los menores, cuando la medida pueda suponer un riesgo para su escolarización, en los términos que determine la ley orgánica correspondiente.","No discriminación, o afecte a las mujeres embarazadas, durante todo el período de gestación.","No devolución, aunque afecte a las mujeres embarazadas cuando no exista riesgo para su salud."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">No devolución, o afecte a las mujeres embarazadas, cuando la medida pueda suponer un riesgo para la gestación o la salud de la madre</mark></span>El <span class=\"ref-norma\">art. 57.6 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"6. La expulsión no podrá ser ejecutada cuando ésta conculcase el principio de no devolución, o afecte a las mujeres embarazadas, cuando la medida pueda suponer un riesgo para la gestación o la salud de la madre.\"</span>"}]},{"a":"ART. 63 bis · PLAZO DE CUMPLIMIENTO VOLUNTARIO (procedimiento ordinario)","q":[{"i":"6-404","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Procedimiento preferente. Incoado el expediente en el que pueda proponerse la expulsión por tratarse de determinados supuestos, la tramitación del mismo tendrá:","o":["Carácter urgente y sumario.","Carácter reservado.","Carácter preferente.","Carácter ordinario, con plazos reducidos a la mitad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Carácter preferente</mark></span>El <span class=\"ref-norma\">art. 63.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"1. Incoado el expediente en el que pueda proponerse la expulsión por tratarse de uno de los supuestos contemplados en el artículo 53.1.d), 53.1.f), 54.1.a), 54.1.b), y 57.2, la tramitación del mismo tendrá carácter preferente.\"</span>"},{"i":"6-405","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Procedimiento preferente. Si el interesado no efectuase alegaciones ni proposición de prueba sobre el contenido del acuerdo de iniciación, éste será considerado como propuesta de resolución. De estimarse la proposición de prueba, ésta se realizará en el plazo máximo de:","o":["Cinco días.","Tres días.","Diez días.","Cuarenta y ocho horas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Tres días</mark></span>El <span class=\"ref-norma\">art. 63.5 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"5. Si el interesado, o su representante, no efectuase alegaciones ni realizasen proposición de prueba sobre el contenido del acuerdo de iniciación, o si no se admitiesen, por improcedentes o innecesarias, de forma motivada, por el instructor las pruebas propuestas, sin cambiar la calificación de los hechos, el acuerdo de iniciación del expediente será considerado como propuesta de resolución con remisión a la autoridad competente para resolver. De estimarse la proposición de prueba, esta se realizará en el plazo máximo de tres días.\"</span>"},{"i":"6-419","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Procedimiento ordinario. Cuando se tramite la expulsión para supuestos distintos a los previstos en el artículo 63, el procedimiento a seguir será:","o":["El preferente.","El sumario.","El ordinario.","El abreviado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El ordinario</mark></span>El <span class=\"ref-norma\">art. 63 bis.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"1. Cuando se tramite la expulsión para supuestos distintos a los previstos en el artículo 63 el procedimiento a seguir será el ordinario.\"</span>"}]},{"a":"ART. 70.1 · EL FORO PARA LA INTEGRACIÓN SOCIAL DE LOS INMIGRANTES","q":[{"i":"6-170","p":"Ley Orgánica 4/2000, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. Constituye el órgano de consulta, información y asesoramiento en materia de integración de los inmigrantes:","o":["El Foro para la Integración Social de los Inmigrantes.","El Observatorio Español del Racismo y la Xenofobia.","La Conferencia Sectorial de Inmigración.","La Comisión Laboral Tripartita de Inmigración."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Foro para la Integración Social de los Inmigrantes</mark></span>Según el <span class=\"ref-norma\">art. 70.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El Foro para la Integración Social de los Inmigrantes, constituido de forma tripartita y equilibrada, por representantes de las Administraciones Públicas, de las asociaciones de inmigrantes y de otras organizaciones con interés e implantación en el ámbito migratorio, incluyendo entre ellas a las organizaciones sindicales y empresariales más representativas, constituye el órgano de consulta, información y asesoramiento en materia de integración de los inmigrantes\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-217","p":"Ley Orgánica 4/2000... Constituye el órgano de consulta, información y asesoramiento en materia de integración de los inmigrantes:","o":["El Foro para la Integración Social de los Inmigrantes.","El Observatorio Español del Racismo y la Xenofobia.","La Conferencia Sectorial de Inmigración.","La Comisión Laboral Tripartita de Inmigración."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Foro para la Integración Social de los Inmigrantes</mark></span>Según el <span class=\"ref-norma\">art. 70.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El Foro para la Integración Social de los Inmigrantes, constituido de forma tripartita y equilibrada, por representantes de las Administraciones Públicas, de las asociaciones de inmigrantes y de otras organizaciones con interés e implantación en el ámbito migratorio, incluyendo entre ellas a las organizaciones sindicales y empresariales más representativas, constituye el órgano de consulta, información y asesoramiento en materia de integración de los inmigrantes\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-253","p":"(Ley Orgánica 4/2000) Ley Orgánica 4/2000... ¿Quién constituye el órgano de consulta, información y asesoramiento en materia de integración de los inmigrantes?","o":["La Conferencia Sectorial de Inmigración.","El Foro para la Integración Social de los Inmigrantes.","Las Subdelegaciones del Gobierno.","El Comité Regional de Inmigración."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Foro para la Integración Social de los Inmigrantes</mark></span>Según el <span class=\"ref-norma\">art. 70.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El Foro para la Integración Social de los Inmigrantes, constituido de forma tripartita y equilibrada, por representantes de las Administraciones Públicas, de las asociaciones de inmigrantes y de otras organizaciones con interés e implantación en el ámbito migratorio, incluyendo entre ellas a las organizaciones sindicales y empresariales más representativas, constituye el órgano de consulta, información y asesoramiento en materia de integración de los inmigrantes\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-300","p":"Ley Orgánica 4/2000, sobre Derechos y Libertades de los Extranjeros en España y su Integración Social. Constituye el órgano de consulta, información y asesoramiento en materia de integración de los inmigrantes:","o":["El Foro para la Integración Social de los Inmigrantes.","El Observatorio Español del Racismo y la Xenofobia.","La Conferencia Sectorial de Inmigración.","La Comisión Laboral Tripartita de Inmigración."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Foro para la Integración Social de los Inmigrantes</mark></span>Según el <span class=\"ref-norma\">art. 70.1 de la LO 4/2000</span>: <span class=\"ref-concepto\">\"El Foro para la Integración Social de los Inmigrantes, constituido de forma tripartita y equilibrada, por representantes de las Administraciones Públicas, de las asociaciones de inmigrantes y de otras organizaciones con interés e implantación en el ámbito migratorio, incluyendo entre ellas a las organizaciones sindicales y empresariales más representativas, constituye el órgano de consulta, información y asesoramiento en materia de integración de los inmigrantes\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1406","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. El Foro para la Integración Social de los Inmigrantes. El Foro para la Integración Social de los Inmigrantes está constituido:","o":["de forma paritaria, por representantes de la Administración General del Estado y de las organizaciones sindicales y empresariales más representativas.","de forma tripartita, por representantes de la Administración General del Estado, de las Comunidades Autónomas y de los Ayuntamientos con mayor población inmigrante, designados por la Conferencia Sectorial de Inmigración.","por representantes de las asociaciones de inmigrantes y de las organizaciones no gubernamentales, designados por el Ministerio competente en materia de inmigración.","de forma tripartita y equilibrada, por representantes de las Administraciones Públicas, de las asociaciones de inmigrantes y de otras organizaciones con interés e implantación en el ámbito migratorio."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">de forma tripartita y equilibrada, por representantes de las Administraciones Públicas, de las asociaciones de inmigrantes y de otras organizaciones con interés e implantación en el ámbito migratorio</mark></span>El <span class=\"ref-norma\">art. 70.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"El Foro para la Integración Social de los Inmigrantes, constituido de forma tripartita y equilibrada, por representantes de las Administraciones Públicas, de las asociaciones de inmigrantes y de otras organizaciones con interés e implantación en el ámbito migratorio\"</span>. Tripartito y equilibrado: Administraciones, asociaciones de inmigrantes y otras organizaciones (incluidas las sindicales y empresariales). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"ART. 62.6 · JUEZ COMPETENTE PARA:","q":[{"i":"6-403","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Ingreso en centros de internamiento. El internamiento se mantendrá por el tiempo imprescindible para los fines del expediente, siendo su duración máxima de:","o":["40 días, y pudiendo acordarse un nuevo internamiento por causas distintas en el mismo expediente, conforme al procedimiento que reglamentariamente se establezca.","72 horas, prorrogables por otras 72 horas por orden judicial motivada.","90 días, y sin que pueda acordarse un nuevo internamiento en ningún caso.","60 días, y sin que pueda acordarse un nuevo internamiento por cualquiera de las causas previstas en un mismo expediente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">60 días, y sin que pueda acordarse un nuevo internamiento por cualquiera de las causas previstas en un mismo expediente</mark></span>El <span class=\"ref-norma\">art. 62.2 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"2. El internamiento se mantendrá por el tiempo imprescindible para los fines del expediente, siendo su duración máxima de 60 días, y sin que pueda acordarse un nuevo internamiento por cualquiera de las causas previstas en un mismo expediente.\"</span>"},{"i":"6-417","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Derechos de los extranjeros internados. El extranjero internado tiene derecho a ser asistido de abogado, que se proporcionará de oficio en su caso, y a comunicarse reservadamente con el mismo:","o":["Incluso fuera del horario general del centro, cuando la urgencia del caso lo justifique.","Únicamente dentro del horario general del centro y previa solicitud por escrito, sin perjuicio de lo que establezcan los tratados internacionales.","Una vez al día, en presencia de un funcionario del centro.","Siempre que lo autorice el Director del centro de internamiento."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Incluso fuera del horario general del centro, cuando la urgencia del caso lo justifique</mark></span>El <span class=\"ref-norma\">art. 62 bis.f) de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"f) A ser asistido de abogado, que se proporcionará de oficio en su caso, y a comunicarse reservadamente con el mismo, incluso fuera del horario general del centro, cuando la urgencia del caso lo justifique.\"</span>"},{"i":"6-418","p":"Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social. Medidas de seguridad en los CIE. Las actuaciones de vigilancia y seguridad interior en los centros podrán suponer inspecciones de los locales y dependencias y, siempre que fuera necesario para la seguridad en los centros:","o":["Registros corporales con desnudo integral de los extranjeros internados.","Intervención de las comunicaciones de los extranjeros internados.","Aislamiento de los extranjeros internados por un máximo de 72 horas.","Registros de personas, ropas y enseres de los extranjeros internados."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Registros de personas, ropas y enseres de los extranjeros internados</mark></span>El <span class=\"ref-norma\">art. 62 quinquies.1 de la LO 4/2000</span> dispone: <span class=\"ref-concepto\">\"1. Las actuaciones de vigilancia y seguridad interior en los centros podrán suponer, en la forma y con la periodicidad que se establezca, inspecciones de los locales y dependencias y siempre que fuera necesario para la seguridad en los centros registros de personas, ropas y enseres de los extranjeros internados.\"</span>"}]},{"a":"LEY DE ASILO · ART. 24 · ADMISIÓN A TRÁMITE","q":[{"i":"6-65","p":"Ley 12/2009, reguladora del Derecho de Asilo y de la Protección Subsidiaria. Procedimiento ordinario. Finalizada la instrucción de los expedientes de solicitud de protección internacional, se elevarán a estudio de _________ que formulará propuesta al Ministro del Interior, quien será el competente para dictar la correspondiente resolución por la que se conceda o deniegue, según proceda, el derecho de asilo o la protección subsidiaria.","o":["El Ministro del Interior.","La Oficina de Asilo y Refugio.","La Comisión Interministerial de Asilo y Refugio.","La Secretaría de Estado de Seguridad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Comisión Interministerial de Asilo y Refugio</mark></span>Según el <span class=\"ref-norma\">art. 24.2 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Finalizada la instrucción de los expedientes, se elevarán a estudio de la Comisión Interministerial de Asilo y Refugio, que formulará propuesta al Ministro del Interior, quien será el competente para dictar la correspondiente resolución por la que se conceda o deniegue, según proceda, el derecho de asilo o la protección subsidiaria\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-186","p":"Ley 12/2009... Procedimiento ordinario. Transcurridos _________ desde la presentación de la solicitud sin que se haya notificado la correspondiente resolución, la misma podrá entenderse _________, sin perjuicio de la obligación de la Administración de resolver expresamente y de lo dispuesto en la presente Ley.","o":["Seis Meses / Desestimada.","Tres Meses / Desestimada.","Seis Meses / Estimada.","Tres Meses / Estimada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Seis Meses / Desestimada</mark></span>Según el <span class=\"ref-norma\">art. 24.3 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Transcurridos seis meses desde la presentación de la solicitud sin que se haya notificado la correspondiente resolución, la misma podrá entenderse desestimada\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-313","p":"Ley 12/2009... Procedimiento ordinario. Transcurridos _________ desde la presentación de la solicitud sin que se haya notificado la correspondiente resolución, la misma podrá entenderse _________, sin perjuicio de la obligación de la Administración de resolver expresamente y de lo dispuesto en la presente Ley.","o":["Seis Meses / Desestimada.","Tres Meses / Desestimada.","Seis Meses / Estimada.","Tres Meses / Estimada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Seis Meses / Desestimada</mark></span>Según el <span class=\"ref-norma\">art. 24.3 de la Ley 12/2009</span>: <span class=\"ref-concepto\">\"Transcurridos seis meses desde la presentación de la solicitud sin que se haya notificado la correspondiente resolución, la misma podrá entenderse desestimada\"</span>. (Verificado con el texto del temario oficial.)"},{"i":"6-ia-1535","p":"Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria. Procedimiento ordinario. Toda solicitud de protección internacional admitida a trámite dará lugar al inicio, por parte del Ministerio del Interior, del correspondiente procedimiento. Si fuera procedente la realización de nuevas entrevistas a las personas solicitantes:","o":["aquéllas deberán realizarse en presencia de un representante del ACNUR y del abogado de la persona solicitante.","aquéllas requerirán la conformidad previa de la persona solicitante.","aquéllas deberán reunir los requisitos previstos para la entrevista de formalización de la solicitud.","aquéllas se realizarán en el plazo máximo de un mes desde la admisión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">aquéllas deberán reunir los requisitos previstos para la entrevista de formalización de la solicitud</mark></span>El <span class=\"ref-norma\">art. 24.1 de la Ley 12/2009</span> dispone: <span class=\"ref-concepto\">\"Si fuera procedente la realización de nuevas entrevistas a las personas solicitantes, aquéllas deberán reunir los requisitos previstos en el artículo 17\"</span>. Las nuevas entrevistas deben reunir los requisitos de la entrevista de formalización. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]}];
